% 二分法自編教材：f(x) = x^2 - 2；此為 MATLAB 程式，非網頁計算器
f = @(x) x.^2 - 2;
xl = 1;
xu = 2;
tol_x = 1e-6; % 中點的絕對位置誤差容許值，不是函數殘差
max_iter = 100; % 最多執行次數，避免無限迴圈
validateattributes(xl, {'double'}, {'scalar','real','finite'});
validateattributes(xu, {'double'}, {'scalar','real','finite','>',xl});
validateattributes(tol_x, {'double'}, {'scalar','real','finite','positive'});
validateattributes(max_iter, {'double'}, {'scalar','real','finite','integer','positive'});
fl = f(xl);
fu = f(xu);
if ~isreal(fl) || ~isreal(fu) || ~isfinite(fl) || ~isfinite(fu)
    error('Bisection:NonFinite', '端點函數值必須是有限實數。');
end
% 連續性必須由使用者分析確認，有限次取樣不能證明連續
converged = false;
history = zeros(0,6); % 欄位：k、xl、xu、xr、f(xr)、更新前半寬
if fl == 0
    xr = xl; fr = fl; bound = 0; converged = true;
elseif fu == 0
    xr = xu; fr = fu; bound = 0; converged = true;
elseif sign(fl) == sign(fu)
    error('Bisection:NoBracket', '端點非零且同號，請重新選擇區間。');
end
fprintf(' k       xl             xu             xr             f(xr)          bound\n');
for k = 1:max_iter
    if converged
        break;
    end
    bound = (xu - xl)/2; % 使用本次更新前的區間，估計本次中點誤差
    xr = xl + bound;
    fr = f(xr);
    if ~isreal(fr) || ~isfinite(fr) || ~isfinite(bound)
        error('Bisection:NonFinite', '中點函數值或區間寬度非有限實數。');
    end
    history(end+1,:) = [k,xl,xu,xr,fr,bound];
    fprintf('%2d  %.12f  %.12f  %.12f  % .12e  %.12e\n', k,xl,xu,xr,fr,bound);
    % 浮點數 fr == 0 表示計算值為零；仍須留意捨入誤差
    if fr == 0 || bound <= tol_x
        converged = true;
        break;
    end
    if xr == xl || xr == xu
        error('Bisection:Stagnation', '浮點精度使中點等於端點，無法繼續縮小區間。');
    end
    % 比較符號，避免直接相乘可能造成溢位
    if sign(fl) ~= sign(fr)
        xu = xr;
        fu = fr;
    else
        xl = xr;
        fl = fr;
    end
end
if ~converged
    error('Bisection:MaxIterations', '已達最大迭代次數，尚未滿足停止條件。');
end
fprintf('近似根 = %.12f；中點誤差界 = %.12e\n', xr, bound);
% 誤差界依賴連續、包根條件；理論界未計入浮點捨入誤差
